MACHINE_SPECS = {
    "e2-standard-4": (4, 16),
    "e2-standard-8": (8, 32),
    "n2-highmem-4": (4, 32),
}

POOLS = [
    ("e2-standard-4", 3, 1),
    ("e2-standard-8", 2, 2),
    ("n2-highmem-4", 4, 1),
]

def pool_capacity(machine_type, node_count):
    vcpu, mem = MACHINE_SPECS[machine_type]
    return (vcpu * node_count, mem * node_count)

def max_pods(machine_type, node_count, pod_cpu):
    vcpu, _ = MACHINE_SPECS[machine_type]
    allocatable = vcpu - 1
    return (allocatable // pod_cpu) * node_count

for mt, count, pod_cpu in POOLS:
    total_vcpu, total_mem = pool_capacity(mt, count)
    pods = max_pods(mt, count, pod_cpu)
    print(f"{mt} x{count} -> {total_vcpu} vCPU, {total_mem} GiB, max {pods} pods")
